const yearSpan=document.getElementById("year");const currentYear=(new Date).getFullYear();yearSpan.textContent=currentYear;console.log("Website loaded successfully! Current year is: "+currentYear);const contactForm=document.getElementById("contact-form");contactForm.addEventListener("submit",function(event){event.preventDefault();const name=document.getElementById("name").value.trim();const email=document.getElementById("email").value.trim();const message=document.getElementById("message").value.trim();if(name===""||email===""||message===""){alert("Please fill out all fields before submitting.")}else{alert("Thank you for your message! I will get back to you soon.");contactForm.reset()}});
